<?php $this->layout('default'); use Moves\Services\CmsSite; use Moves\Support\CmsView as V; $locations = ['header' => 'Cabeçalho', 'footer' => 'Rodapé']; ?>
<div class="cms-alert cms-alert-info">Enquanto um local não tiver itens visíveis, o site mantém a navegação original do template.</div>
<form class="cms-card" method="post" action="/acao/menu-save"><h2>Novo item</h2><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('Local', 'location', 'header', ['type' => 'select', 'choices' => $locations]) ?><?= V::field('Rótulo', 'label', '', ['required' => true]) ?><?= V::field('Destino', 'url', '', ['required' => true, 'help' => 'Comece com / ou https://']) ?><?= V::field('Ordem', 'sort_order', '0', ['type' => 'number']) ?></div><?= V::field('Visível', 'is_visible', '1', ['type' => 'checkbox']) ?><button class="cms-btn-primary">Salvar</button></form>
<?php foreach ($locations as $location => $name): $items = CmsSite::menu($location); ?><div class="cms-card"><h2><?= V::e($name) ?></h2><?php if ($items === []): ?><?= V::empty('Sem itens neste local.') ?><?php endif; ?><?php foreach ($items as $item): ?><form method="post" action="/acao/menu-save" class="cms-filters"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="location" value="<?= V::e($location) ?>"><div class="cms-field"><label>Rótulo<input name="label" value="<?= V::e($item['label']) ?>"></label></div><div class="cms-field"><label>Destino<input name="url" value="<?= V::e($item['url']) ?>"></label></div><div class="cms-field"><label>Ordem<input type="number" name="sort_order" value="<?= (int) $item['sort_order'] ?>"></label></div><label class="cms-check"><input type="hidden" name="is_visible" value="0"><input type="checkbox" name="is_visible" value="1"<?= $item['is_visible'] ? ' checked' : '' ?>> Visível</label><button class="cms-btn">Salvar</button></form><?= V::actionButton('menu-delete', 'Excluir', ['id' => $item['id']], 'cms-btn-danger', 'Excluir este item?') ?><?php endforeach; ?></div><?php endforeach; ?>
